  ('amigurumi-gato-cachecol', 'Amigurumi Gato Cachecol', 'pronta_entrega', 89, null, null, null, array['/produtos/amigurumi-gato-cachecol.webp']::text[], 'Gatinho preto em fio de veludo, com cachecol azul de tricô feito à mão. Uma peça só, pronta pra ganhar um novo lar.', 'Fio de veludo (chenille), enchimento antialérgico', '13cm de altura', 'Não lavar — limpar com pano levemente úmido.', false),
  ('buque-de-tulipas-croche', 'Buquê de Tulipas de Crochê', 'pronta_entrega', 75, 'buquê com 5 flores', null, null, array['/produtos/buque-de-tulipas-croche.webp']::text[], 'Buquê de tulipas em crochê, hastes revestidas e laço de fita — não murcha nunca. Um presente diferente pra quem você gosta.', 'Fio de algodão, hastes de arame revestido, fita de cetim', '22cm de altura', 'Não lavar — objeto decorativo, limpar a seco se precisar.', false),
  ('kit-panos-de-prato-xadrez', 'Kit Panos de Prato Xadrez', 'pronta_entrega', 98, 'kit com 2', null, null, array['/produtos/kit-panos-de-prato-xadrez.webp']::text[], 'Dupla de panos de prato em xadrez de crochê, um verde e um vinho, com barrado em concha. Deixam a cozinha mais aconchegante.', 'Fio de algodão 100%, tons verde e vinho', '40cm x 30cm cada', 'Lavar à mão com água fria e sabão neutro.', false),
  ('sousplat-rendado-flor', 'Sousplat Rendado Flor', 'pronta_entrega', 55, null, null, null, array['/produtos/sousplat-rendado-flor.webp']::text[], 'Sousplat redondo em crochê branco, com barrado em relevo de florzinhas rosa. Dá um toque especial na mesa posta.', 'Fio de algodão fio 8', '32cm de diâmetro', 'Lavar à mão, passar levemente a ferro se necessário.', false),
  ('amigurumi-coelho-laco-preto', 'Amigurumi Coelho Laço Preto', 'pronta_entrega', 92, null, null, null, array['/produtos/amigurumi-coelho-laco-preto.webp']::text[], 'Coelhinho de orelha caída em fio de veludo caramelo, olhos de botão e laço de cetim preto. Peça única, pronta entrega.', 'Fio de veludo (chenille), botões, fita de cetim', '18cm de altura', 'Não lavar — limpar com pano levemente úmido.', false)
